{
  "title": "Reykjavik on a shoestring",
  "summary": "A slower, cheaper Sunday around Reykjavik, keeping the whales and swapping pricey stops for free local colour.",
  "stops": [
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The crew's must-see; those big sea faces are worth every minute, even on a thrifty day.",
      "start_by": "15:45"
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "Free, lively, and full of local oddities; a proper Reykjavik rummage without opening the wallet.",
      "start_by": "16:00"
    },
    {
      "poi_id": "p17",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch with rye bread and a view of Hallgrímskirkja; cheaper than the grill and kinder to the budget.",
      "start_by": "20:00"
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at the food hall keeps everyone happy and the bill low; plenty of choices for a crew of five.",
      "start_by": "22:00"
    }
  ]
}
